      document.querySelector('#dialogBody input[name="brand"]').value="Audit Brand Added";
      document.querySelector('#dialogSubmit')?.click();
      const addSaved=await waitFor(()=>rows.some(row=>row.brand==="Audit Brand Added"));
      await waitFor(()=>!document.querySelector("#appDialog")?.open);
      const added=rows.find(row=>row.brand==="Audit Brand Added");
      openGenericDialog(genericModules.brands,added,columns.columns);
      const editOpen=Boolean(document.querySelector("#appDialog")?.open);
      document.querySelector('#dialogBody input[name="brand"]').value="Audit Brand Revised";
      document.querySelector('#dialogSubmit')?.click();
      const editSaved=await waitFor(()=>calls.some(call=>call.payload._action==="update")&&rows.some(row=>row.brand==="Audit Brand Revised"));
      await waitFor(()=>!document.querySelector("#appDialog")?.open);
      const revised=rows.find(row=>row.brand==="Audit Brand Revised");
      deleteGenericRow(genericModules.brands,revised);
      const deleteConfirm=Boolean(document.querySelector("#appDialog")?.open);
      document.querySelector("#dialogSubmit")?.click();
      const deleteSaved=await waitFor(()=>calls.some(call=>call.payload._action==="delete")&&!rows.some(row=>row.brand==="Audit Brand Revised"));
      await waitFor(()=>!document.querySelector("#appDialog")?.open);
      return{firstPageRows,searchFilterCount,secondPageVisible,groupFilterCount,inactiveFilterCount,addOpen,addSaved,editOpen,editSaved,deleteConfirm,deleteSaved,actions:calls.map(call=>call.payload._action||"insert"),columnCount:columns.columns.length};
