async function auditQuickSaleFailureRecovery(evaluate) {
  return evaluate(`(async () => {
    const original = { page, apiFetch, hydrateDesktop, stock: db.stock };
    const calls = [];
    const tenantId = String(currentAuthUser?.tenant_id || "").trim();
    const draftKey = tenantId ? "ayec.quick_sale_draft.v1." + encodeURIComponent(tenantId) : "";
    const originalDraft = draftKey ? localStorage.getItem(draftKey) : null;
    db.stock = [{id: 99101, name: "QA POS Recovery", code: "QPOS-R1", barcode: "12011", qty: 1, sell: 18, currency: "TRY"}];
    apiFetch = async (url, options = {}) => {
      if (String(url).includes("bank_accounts")) return {rows: []};
      if (String(url).includes("quick-commit")) {
        calls.push({url: String(url), payload: JSON.parse(options.body || "{}")});
        throw new Error("Simulated transaction failure");
      }
      return {rows: [], count: 0, ok: true};
    };
    hydrateDesktop = async () => {};
    try {
      const manifest = await (await fetch("/dialogs.generated.json")).json();
      const entry = manifest.dialogs.find(dialog => dialog.key === "quick_sale_dialog");
      if (!entry) return {entryFound: false};
      await openManifestDialog(entry);
      const scanner = document.querySelector("#quickSaleSearch");
      if (!scanner) return {entryFound: true, opened: false};
      scanner.value = "12011";
      scanner.dispatchEvent(new Event("input", {bubbles: true}));
      scanner.dispatchEvent(new KeyboardEvent("keydown", {key: "Enter", bubbles: true, cancelable: true}));
      document.querySelector("[data-qpos-add]")?.click();
      const itemAdded = Number(document.querySelector("[data-qpos-qty]")?.value) === 1;
      document.querySelector("[data-qpos-checkout]")?.click();
      const confirmOpen = Boolean(document.querySelector("#appDialog")?.open);
      document.querySelector("#dialogSubmit")?.click();
      for (let i = 0; i < 80 && !calls.length; i++) await new Promise(resolve => setTimeout(resolve, 10));
      await new Promise(resolve => setTimeout(resolve, 80));
      const dialogOpenAfterFailure = Boolean(document.querySelector("#appDialog")?.open);
      const cartRetained = Number(document.querySelector("[data-qpos-qty]")?.value) === 1;
      const errorShown = document.querySelector("#toastRoot .toast.error")?.textContent.includes("Simulated transaction failure") === true;
      const failedRequest = calls[0] || null;
      document.querySelector("#appDialog")?.close("audit-cleanup");
      document.querySelector("[data-qpos-close]")?.click();
      return {entryFound: true, opened: true, itemAdded, confirmOpen, failedRequest, dialogOpenAfterFailure, cartRetained, errorShown};
    } finally {
      document.querySelector("#appDialog")?.close("audit-cleanup");
      document.querySelector("[data-qpos-close]")?.click();
      if (draftKey) {
        if (originalDraft === null) localStorage.removeItem(draftKey);
        else localStorage.setItem(draftKey, originalDraft);
      }
      page = original.page;
      apiFetch = original.apiFetch;
      hydrateDesktop = original.hydrateDesktop;
      db.stock = original.stock;
      render();
    }
  })()`);
}

